  "inlineSchema": "datasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel User {\n  id             Int                  @id @default(autoincrement())\n  email          String               @unique\n  password       String\n  name           String\n  role           String // 'DOCTOR', 'SECRETARY', 'ADMIN'\n  specialty      String? // Optional specialty for doctors\n  createdAt      DateTime             @default(now())\n  updatedAt      DateTime             @updatedAt\n  availabilities DoctorAvailability[]\n  appointments   Appointment[]\n  dictations     MedicalDictation[]\n}\n\nmodel Patient {\n  id                Int                @id @default(autoincrement())\n  firstName         String\n  lastName          String\n  dob               DateTime\n  phone             String             @unique\n  email             String?\n  password          String? // Optionnel : certains patients peuvent être créés par le secrétariat sans compte web\n  insurance         String? // 'Carte Vitale', 'Mutuelle', etc.\n  treatingPhysician String?\n  consentGdpr       Boolean            @default(false)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  appointments      Appointment[]\n  callLogs          CallLog[]\n  notifications     Notification[]\n  dictations        MedicalDictation[]\n}\n\nmodel DoctorAvailability {\n  id           Int       @id @default(autoincrement())\n  doctorId     Int\n  doctor       User      @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  dayOfWeek    Int? // 0 = Sunday, 1 = Monday, ..., 6 = Saturday (for weekly recurring availability)\n  startTime    String // \"HH:MM\" (e.g. \"09:00\")\n  endTime      String // \"HH:MM\" (e.g. \"17:00\")\n  specificDate DateTime? // Specific date for exceptions/one-off shifts (overrides dayOfWeek if set)\n  isAvailable  Boolean   @default(true) // Can be false to block out specific times (e.g. lunch break, leave)\n\n  @@index([doctorId])\n}\n\nmodel Appointment {\n  id            Int            @id @default(autoincrement())\n  patientId     Int\n  patient       Patient        @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  doctorId      Int\n  doctor        User           @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  startTime     DateTime\n  endTime       DateTime\n  status        String // 'PENDING', 'CONFIRMED', 'CANCELLED', 'MOVED', 'URGENT'\n  notes         String?        @db.Text\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  notifications Notification[]\n\n  @@index([patientId])\n  @@index([doctorId])\n}\n\nmodel CallLog {\n  id             Int       @id @default(autoincrement())\n  direction      String // 'INBOUND', 'OUTBOUND'\n  phoneNumber    String\n  status         String // 'COMPLETED', 'MISSED', 'IN_PROGRESS'\n  startTime      DateTime  @default(now())\n  endTime        DateTime?\n  duration       Int? // in seconds\n  transcript     String?   @db.Text // JSON or text representing conversation turns\n  summary        String?   @db.Text // AI generated summary of the call\n  classification String? // 'EMERGENCY', 'APPOINTMENT_BOOKING', 'APPOINTMENT_MODIFICATION', 'INFO_REQUEST', 'ADMINISTRATIVE'\n  language       String    @default(\"Français\")\n  patientId      Int?\n  patient        Patient?  @relation(fields: [patientId], references: [id], onDelete: SetNull)\n  createdAt      DateTime  @default(now())\n\n  @@index([patientId])\n}\n\nmodel Faq {\n  id        Int      @id @default(autoincrement())\n  question  String   @db.Text\n  answer    String   @db.Text\n  category  String // 'horaires', 'adresse', 'parking', 'tarifs', 'specialites', 'preparations'\n  createdAt DateTime @default(now())\n}\n\nmodel Notification {\n  id             Int          @id @default(autoincrement())\n  appointmentId  Int?\n  appointment    Appointment? @relation(fields: [appointmentId], references: [id], onDelete: SetNull)\n  patientId      Int\n  patient        Patient      @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  type           String // 'SMS', 'EMAIL', 'WHATSAPP'\n  status         String // 'PENDING', 'SENT', 'FAILED'\n  messageContent String       @db.Text\n  sentAt         DateTime?\n  createdAt      DateTime     @default(now())\n\n  @@index([appointmentId])\n  @@index([patientId])\n}\n\nmodel MedicalDictation {\n  id            Int      @id @default(autoincrement())\n  doctorId      Int\n  doctor        User     @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  patientId     Int\n  patient       Patient  @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  rawTranscript String   @db.Text\n  summary       String?  @db.Text\n  notes         String?  @db.Text // Clinical notes draft\n  exportPdfUrl  String?\n  createdAt     DateTime @default(now())\n\n  @@index([doctorId])\n  @@index([patientId])\n}\n",
